css:
body {
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    background-color: #f9f9f9;
    margin: 0;
    padding: 20px;
}

.receipt-container {
    max-width: 380px;
    margin: 0 auto;
    background: white;
    box-shadow: 0 0 20px rgba(0,0,0,0.1);
    border-radius: 10px;
    overflow: hidden;
    padding: 25px;
}

.header {
    text-align: center;
    margin-bottom: 25px;
    border-bottom: 2px solid #4CAF50;
    padding-bottom: 15px;
}

.company-name {
    color: #2E7D32;
    font-weight: 700;
    font-size: 1.4rem;
    margin: 0;
    letter-spacing: 1px;
}

.park-name {
    color: #333;
    font-weight: 600;
    font-size: 1.1rem;
    margin: 5px 0 0;
}

.receipt-info {
    display: flex;
    justify-content: space-between;
    margin-bottom: 20px;
    font-size: 0.9rem;
}

.receipt-title {
    font-size: 1.5rem;
    font-weight: 700;
    color: #333;
    margin-bottom: 15px;
    text-align: center;
}

table {
    width: 100%;
    border-collapse: collapse;
    margin: 15px 0;
}

th {
    background-color: #5eff74;
    color: white;
    padding: 6px 4px;
    text-align: left;
    font-weight: 600;
}

td {
    padding: 6px 4px;
    border-bottom: 1px solid #eee;
}

.text-right {
    text-align: right;
}

.total-section {
    background-color: #f5f5f5;
    padding: 15px;
    border-radius: 5px;
    margin: 20px 0;
    text-align:left;
    font-weight: 500;
    font-size: 1.1rem;
    font-size:16px;
}

.payment-method {
    background-color: #a2f2e9;
    padding: 12px;
    border-radius: 5px;
    margin-bottom: 20px;
    font-weight: 500;
    font-size:16px;
}

.footer {
    text-align: center;
    margin-top: 25px;
    color: #666;
    font-size: 0.9rem;
}

.thank-you {
    font-weight: 600;
    color: #2E7D32;
    margin-bottom: 10px;
    font-size: 1.1rem;
}

.tagline {
    font-style: italic;
    margin: 8px 0;
}

.contact-info {
    margin-top: 15px;
    line-height: 1.5;
}

.divider {
    border-top: 1px dashed #ccc;
    margin: 15px 0;
}
table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;   /* IMPORTANT */
    font-size: 12px;       /* receipts need small text */
}
